mapper.select:
SELECT mur.id, mb.id AS msg_id, mb.module_id, mb.module_name, mb.data_id, mb.msg_flag, mb.msg_type, mb.msg_title, mb.msg_body, mb.msg_href FROM msg_user_rel mur LEFT JOIN msg_base mb ON mur.msg_id = mb.id WHERE mur.user_id = #{pageDTO.userId} AND mur.del_flag = #{pageDTO.delFlag}
AND mb.msg_flag = #{pageDTO.msgFlag}
AND mur.read_flag = #{pageDTO.readFlag}
ORDER BY mb.create_time DESC
